	@Test
	void immutableManifestRejectsSameSizeWrongFixture(@TempDir Path directory) throws Exception {
		Path dataDirectory = directory.resolve("lmdb");
		Path triplesDirectory = Files.createDirectories(dataDirectory.resolve("triples"));
		Path valuesDirectory = Files.createDirectories(dataDirectory.resolve("values"));
		Files.writeString(triplesDirectory.resolve("data.mdb"), "original-triples");
		Files.writeString(valuesDirectory.resolve("data.mdb"), "original-values");
		Files.writeString(triplesDirectory.resolve("lock.mdb"), "ephemeral-lock");

		Path manifest = directory.resolve("fixture-manifest.json");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc");
		config.setSketchEstimatorEvidenceMode("snapshot-only");
		QueryPlanSnapshotStoreSupport.writeLmdbStoreManifest(dataDirectory, manifest, config);
		assertDoesNotThrow(
				() -> QueryPlanSnapshotStoreSupport.validateLmdbStoreManifest(dataDirectory, manifest, config));

		Files.writeString(valuesDirectory.resolve("data.mdb"), "corrupted-value");

		IOException mismatch = assertThrows(IOException.class,
				() -> QueryPlanSnapshotStoreSupport.validateLmdbStoreManifest(dataDirectory, manifest, config));
		assertTrue(mismatch.getMessage().contains("values/data.mdb"), mismatch.getMessage());
		assertTrue(mismatch.getMessage().contains("SHA-256"), mismatch.getMessage());
	}

