	@Test
	void immutableManifestIgnoresLocksAndRejectsConfigurationDrift(@TempDir Path directory) throws Exception {
		Path dataDirectory = directory.resolve("lmdb");
		Path triplesDirectory = Files.createDirectories(dataDirectory.resolve("triples"));
		Files.writeString(triplesDirectory.resolve("data.mdb"), "persistent-data");
		Path lock = triplesDirectory.resolve("lock.mdb");
		Files.writeString(lock, "first-lock-state");
		Path manifest = directory.resolve("fixture-manifest.json");
		LmdbStoreConfig snapshotOnly = themeBenchmarkConfig("snapshot-only");
		QueryPlanSnapshotStoreSupport.writeLmdbStoreManifest(dataDirectory, manifest, snapshotOnly);

		Files.writeString(lock, "different-lock-state");
		assertDoesNotThrow(() -> QueryPlanSnapshotStoreSupport.validateLmdbStoreManifest(dataDirectory, manifest,
				snapshotOnly));

		LmdbStoreConfig adaptive = themeBenchmarkConfig("adaptive");
		IOException mismatch = assertThrows(IOException.class,
				() -> QueryPlanSnapshotStoreSupport.validateLmdbStoreManifest(dataDirectory, manifest, adaptive));
		assertTrue(mismatch.getMessage().contains("configuration mismatch"), mismatch.getMessage());
		assertTrue(mismatch.getMessage().contains("sketchEstimatorEvidenceMode"), mismatch.getMessage());
		assertTrue(mismatch.getMessage().contains("expected=snapshot-only"), mismatch.getMessage());
		assertTrue(mismatch.getMessage().contains("actual=adaptive"), mismatch.getMessage());
	}

	private static LmdbStoreConfig themeBenchmarkConfig(String evidenceMode) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc");
		config.setForceSync(false);
		config.setSketchEstimatorEvidenceMode(evidenceMode);
		config.setValueDBSize(1_073_741_824L);
		config.setTripleDBSize(config.getValueDBSize());
		config.setSketchEstimatorSubjectBucketCount(4096);
		config.setSketchEstimatorPredicateBucketCount(64);
		config.setSketchEstimatorObjectBucketCount(4096);
		config.setSketchEstimatorContextBucketCount(16);
		config.setSketchEstimatorContextPairSketchesEnabled(false);
		return config;
	}
